[Form]
public class METCSDWaveList extends FormRun
{
    InventTransferTable     inventTransferTable;
    InventTransferLine      inventTransferLine;
    METCSDWaveTable         waveTableTmp;
    str inventlocationidVar;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        inventlocationidVar
    #endmacro



}

/* SysLastValue framework's needed methods */

/// <summary>
/// get the user id
/// </summary>
/// <returns>return the user id</returns>
private UserId lastValueUserId()
{
    return curUserId();
}

/// <summary>
/// Get the last value
/// </summary>
/// <returns>return the last value</returns>
private UtilElementType lastValueType()
{
    return UtilElementType::Form;
}

/// <summary>
/// get the last value element name
/// </summary>
/// <returns>return the string value</returns>
private IdentifierName lastValueElementName()
{
    return this.name();
}

/// <summary>
/// get the last value design name.
/// </summary>
/// <returns>return the string value</returns>
private IdentifierName lastValueDesignName()
{
    return '';
}

/// <summary>
/// get the last value dataareaid
/// </summary>
/// <returns>return the string value</returns>
DataAreaId lastValueDataAreaId()
{
    return curext();
}

/// <summary>
/// initlize the default parm default.
/// </summary>
void initParmDefault()
{
    // Don't need to initialize any of the controls.
}

/// <summary>
/// pack the last values
/// </summary>
/// <returns>retunr the array value</returns>
public container pack()
{
    this.getControlValuesForSysLastValues();
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// unpack the last value
/// </summary>
/// <param name = "packedClass">packedClass</param>
/// <returns>return the boolean value</returns>
public boolean unpack(container packedClass)
{
    Integer version = conPeek(packedClass, 1);
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = packedClass;
            break;
        default:
            return false;
    }
    return true;
}

/// <summary>
/// save the last value on closing the form
/// </summary>
public void close()
{
    xSysLastValue::saveLast(this);
    super();
}

/// <summary>
/// run the form method
/// </summary>
public void run()
{
    super();
    xSysLastValue::getLast(this);
    this.setControlValuesFromSysLastValues();
}

/// <summary>
/// get control for last sys value.
/// </summary>
void getControlValuesForSysLastValues()
{
    inventlocationidVar = InventlocationIdToFilter.text();
}

/// <summary>
/// set control of last sys value.
/// </summary>
void setControlValuesFromSysLastValues()
{
    InventlocationIdToFilter.text(inventlocationidVar);
}

/// <summary>
/// init the form method
/// </summary>
public void init()
{
    date systemDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    super();
    ShipDateFilter.dateValue(systemDate);
    DaysForwardFilter.value(0);
    WaveOnlyFilter.checked(true);
    element.DeleteRecord();
}

/// <summary>
/// validate the form method
/// </summary>
/// <returns>return the boolean value</returns>
public boolean validate()
{
    #define.MinAllowedDaysBack(365)
    boolean ret = true;
    date today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    date minAllowedDate = today - #MinAllowedDaysBack;

    // Check if FromDateFilter is empty (mandatory check)
    if (!ShipDateFilter.dateValue())
    {
        error("@MET:ShipDateIsMandatory");
        ret = false;
    }
    // Check if From date is earlier than the minimum allowed date
    else if (ShipDateFilter.dateValue() < minAllowedDate)
    {
        error(strFmt("@MET:ShipDateCannotBeEarlier", minAllowedDate));
        ShipDateFilter.dateValue(minAllowedDate);
        ret = false;
    }

    // Check if Warehouse is empty (mandatory check)
    if (!InventlocationIdToFilter.valueStr() || !InventLocation::find(InventlocationIdToFilter.valueStr()))
    {
        error("@MET:WarehouseMandatory");
        ret = false;
    }

    return ret;
}

/// <summary>
/// Delete the current User Id Record
/// </summary>
public void DeleteRecord()
{
    ttsbegin;
    delete_from waveTableTmp where waveTableTmp.CreatedBy == curUserId();
    ttscommit;
}

/// <summary>
/// execute the Query
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource  queryBuildDataSource;
    QueryBuildRange       range1,range2,range3;
    METCSDQtyDiff           CSDQtyDiff;
    NoYes                 showWaveOnly;

    CSDQtyDiff = str2Enum(CSDQtyDiff,QtyDiffFilter.valueStr());
    showWaveOnly = WaveOnlyFilter.checked();

    queryBuildDataSource = this.query().dataSourceTable(tablenum(METCSDWaveTable));
    queryBuildDataSource.clearRanges();
    range1 = queryBuildDataSource.addRange(fieldnum(METCSDWaveTable, CreatedBy));
    range1.value(queryValue(curUserId()));

    if (CSDQtyDiff == METCSDQtyDiff::DiffernceOnly)
    {
        range2 = queryBuildDataSource.addRange(fieldnum(METCSDWaveTable, QtyDifference));
        range2.value(SysQuery::valueNot(0));
    }

    if (showWaveOnly == NoYes::Yes)
    {
        range3 = queryBuildDataSource.addRange(fieldnum(METCSDWaveTable, WaveId));
        range3.value(SysQuery::valueNot(""));
    }

    super();
}

/// <summary>
/// validate and apply filters
/// </summary>
public void clicked()
{
    InventLocation  inventLocation;
    InventLocationID inventLocationId = InventlocationIdToFilter.valueStr();
    int daysforward = DaysForwardFilter.value();
    TransDate fromDate = ShipDateFilter.dateValue();
    NoYesId waveOnly = WaveOnlyFilter.checked();
    InventDim   inventDim;
    TransDate toDate;
    if (daysforward > 0)
    {
        toDate = ShipDateFilter.dateValue() + daysforward;
    }
    inventLocation = InventLocation::find(inventLocationId);
    super();

    if (element.validate())
    {
        ttsbegin;
        element.DeleteRecord();
        ttscommit;

        if (daysforward > 0)
        {
            insert_recordset waveTableTmp(TransferId,ShipDate,ReceiveDate,ItemId,QtyTransfer,QtyShipped,PdsCWQtyTransfer,PdsCWQtyShipped,InventTranslineRecID,InventLocationIdFrom,InventLocationIdTo,TransferStatus)
            select TransferId,ShipDate,ReceiveDate,ItemId,QtyTransfer,QtyShipped,PdsCWQtyTransfer,PdsCWQtyShipped,RecId from inventTransferLine
                join InventLocationIdFrom,InventLocationIdTo,TransferStatus from inventTransferTable
                where inventTransferTable.TransferId == inventTransferLine.TransferId
                    && inventTransferLine.ShipDate >= fromDate
                    && inventTransferLine.ShipDate <= toDate
                    && inventTransferTable.InventLocationIdTo == inventLocationId;


            while select forupdate waveTableTmp
                where waveTableTmp.CreatedBy == curUserId()
            {
                ttsbegin;                       
                waveTableTmp.ProductName = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber( waveTableTmp.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
                waveTableTmp.UnitId = InventTableModule::find(waveTableTmp.ItemId,ModuleInventPurchSales::Invent).UnitId;
                waveTableTmp.PdsCWUnitId = PdsCatchWeightItem::find(waveTableTmp.ItemId).PdsCWUnitId;

                if(!waveTableTmp.PdsCWQtyTransfer)
                {
                    waveTableTmp.QtyDifference = waveTableTmp.QtyTransfer - waveTableTmp.QtyShipped;
                }
                else
                {
                    waveTableTmp.QtyDifference = waveTableTmp.PdsCWQtyTransfer - waveTableTmp.PdsCWQtyShipped;
                }

                if(waveOnly == NoYes::Yes && InventLocation::find(waveTableTmp.InventLocationIdTo).METWaveRequired)
                {
                    waveTableTmp.WaveId = METWaveLine::findByDocumentRefRecId(waveTableTmp.InventTranslineRecID).WaveId;
                    waveTableTmp.WaveNumber = METWaveTable::find(METWaveLine::findByDocumentRefRecId(waveTableTmp.InventTranslineRecID).WaveId).WaveNumber;

                }

                waveTableTmp.CSDTOType = METInventTransferTableExt::findByTransferId(waveTableTmp.TransferId).CSDTOType;

                inventDim.clear();
                inventDim.InventLocationId = waveTableTmp.InventLocationIdTo;
                inventDim.InventSiteId = InventLocation::find(waveTableTmp.InventLocationIdTo).InventSiteId;
                inventDim = InventDim::findOrCreate(inventDim);
                waveTableTmp.SalesUnit = InventTable::find(waveTableTmp.ItemId).inventItemSalesSetup(inventDim.inventDimId).METSalesUnit;
                waveTableTmp.update();
                ttscommit;     
            }

        }
        else
        {
            insert_recordset waveTableTmp(TransferId,ShipDate,ReceiveDate,ItemId,QtyTransfer,QtyShipped,PdsCWQtyTransfer,PdsCWQtyShipped,InventLocationIdFrom,InventLocationIdTo,TransferStatus)
            select TransferId,ShipDate,ReceiveDate,ItemId,QtyTransfer,QtyShipped,PdsCWQtyTransfer,PdsCWQtyShipped from inventTransferLine
                join InventLocationIdFrom,InventLocationIdTo,TransferStatus from inventTransferTable
                where inventTransferTable.TransferId == inventTransferLine.TransferId
                    && inventTransferLine.ShipDate == fromDate
                && inventTransferTable.InventLocationIdTo == inventLocationId;

            while select forupdate waveTableTmp
                where waveTableTmp.CreatedBy == curUserId()
            {
                ttsbegin;
                waveTableTmp.ProductName = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber( waveTableTmp.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
                waveTableTmp.UnitId = InventTableModule::find(waveTableTmp.ItemId,ModuleInventPurchSales::Invent).UnitId;
                waveTableTmp.PdsCWUnitId = PdsCatchWeightItem::find(waveTableTmp.ItemId).PdsCWUnitId;

                if(!waveTableTmp.PdsCWQtyTransfer)
                {
                    waveTableTmp.QtyDifference = waveTableTmp.QtyTransfer - waveTableTmp.QtyShipped;
                }
                else
                {
                    waveTableTmp.QtyDifference = waveTableTmp.PdsCWQtyTransfer - waveTableTmp.PdsCWQtyShipped;
                }

                if(waveOnly == NoYes::Yes && InventLocation::find(waveTableTmp.InventLocationIdTo).METWaveRequired)
                {
                    waveTableTmp.WaveId = METWaveLine::findByDocumentRefRecId(waveTableTmp.InventTranslineRecID).WaveId;
                    waveTableTmp.WaveNumber = METWaveTable::find(METWaveLine::findByDocumentRefRecId(waveTableTmp.InventTranslineRecID).WaveId).WaveNumber;

                }
                waveTableTmp.CSDTOType = METInventTransferTableExt::findByTransferId(waveTableTmp.TransferId).CSDTOType;
                inventDim.clear();
                inventDim.InventLocationId = waveTableTmp.InventLocationIdTo;
                inventDim.InventSiteId = InventLocation::find(waveTableTmp.InventLocationIdTo).InventSiteId;
                inventDim = InventDim::findOrCreate(inventDim);
                waveTableTmp.SalesUnit = InventTable::find(waveTableTmp.ItemId).inventItemSalesSetup(inventDim.inventDimId).METSalesUnit;
                waveTableTmp.update();
                ttscommit;
            }
        }
        //METCSDWaveTable.setTmpData(waveTableTmp);
        METCSDWaveTable_DS.research(true);
        METCSDWaveTable_DS.executeQuery();
    }
}

/// <summary>
/// modified the datasource of execute query
/// </summary>
/// <returns></returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    METCSDWaveTable_DS.executeQuery();

    return ret;
}

